\label{pro-gen}
Let $\xi = \pm 1$ and $\lambda \in {\mathcal P}$.
The following relations are valid. 
\begin{align}
S_{\lambda}(X|Y)&=\sum_{\mu \in {\mathcal P}}
\sum_{\kappa \in {\mathcal P}^{+} } \mathrm{LR}^{\lambda}_{\kappa , \mu} 
S_{[\mu]}(X|Y)
\label{dc-1a}
\\
  
&=\sum_{\mu \in {\mathcal P}}
\sum_{\kappa \in {\mathcal P}^{-} }
 \mathrm{LR}^{\lambda}_{\kappa , \mu} 
S_{\langle \mu \rangle}(X |Y),
\label{dc-1b}
\end{align}
            
\begin{align}
S_{\lambda}(X|Y \sqcup \{\xi \})&=\sum_{\mu \in {\mathcal P}}
\sum_{\kappa \in {\mathcal P}^{-} } \mathrm{LR}^{\lambda}_{\kappa , \mu} 
S_{[\mu]}(X \sqcup \{-\xi \} |Y)
\label{dc-2a}
\\
  
&=\sum_{\mu,\nu \in {\mathcal P}}
(-\xi)^{|\nu|} \mathrm{LR}^{\lambda}_{\nu , \mu} 
S_{[\mu]}(X |Y),
\label{dc-2b}
\end{align}
            
\begin{align}
S_{\lambda}(X \sqcup \{\xi \}|Y)&=\sum_{\mu \in {\mathcal P}}
\sum_{\kappa \in {\mathcal P}^{+} } \mathrm{LR}^{\lambda}_{\kappa , \mu} 
S_{\langle \mu \rangle}(X |Y\sqcup \{-\xi \})
\label{dc-3a}
\\
  
&=\sum_{\mu,\nu \in {\mathcal P}}
\xi^{|\nu|} \mathrm{LR}^{\lambda}_{\nu , \mu} 
S_{\langle \mu \rangle}(X |Y),
\label{dc-3b}
\end{align}
            
\begin{align}
S_{\lambda}(X|Y\sqcup \{1,-1\})&=\sum_{\mu \in {\mathcal P}}
\sum_{\kappa \in {\mathcal P}^{-} } \mathrm{LR}^{\lambda}_{\kappa , \mu} 
S_{[\mu ]}(X |Y),
\label{dc-4}
\end{align}
  
\begin{align}
S_{\lambda}(X\sqcup \{1,-1\}|Y)&=\sum_{\mu \in {\mathcal P}}
\sum_{\kappa \in {\mathcal P}^{+} } \mathrm{LR}^{\lambda}_{\kappa , \mu} 
S_{\langle \mu \rangle}(X |Y).
\label{dc-4du}
\end{align}

\label{Cauchy-lem}
The following relations are valid.
\begin{align}
\sum_{\lambda \in {\mathcal P}}
S_{\lambda}(X|Y)S_{\lambda }(T)
&=\prod_{j}
\left(
\frac{\prod_{i} (1-t_{j}y_{i})}{\prod_{i} (1-t_{j}x_{i})}
\right) ,
\label{co-A}
\\
  
\sum_{\lambda \in {\mathcal P}}
S_{[\lambda]}(X|Y)S_{\lambda }(T)
&=\prod_{j }
\left(
\frac{\prod_{i} (1-t_{j}y_{i})}{\prod_{i} (1-t_{j}x_{i})}
\right)
 \prod_{i \le j}(1-t_{i}t_{j}),
\label{co-B}
\\
  
\sum_{\lambda \in {\mathcal P}}
S_{\langle \lambda \rangle}(X|Y)S_{\lambda }(T)
&=\prod_{j}
\left(
\frac{\prod_{i} (1-t_{j}y_{i})}{\prod_{i} (1-t_{j}x_{i})}
\right)
 \prod_{i < j}(1-t_{i}t_{j}).
\label{co-C}
\end{align}

It suffices to show that the following relation holds 
for any $m \in {\mathbb Z}_{\ge 1}$:
\begin{align}
\sum_{\lambda \in {\mathcal P}}
S_{[\lambda]}(X|Y)S_{\lambda }(T^{(m)})
&=\prod_{j=1}^{m}
\left(
\frac{\prod_{i} (1-t_{j}y_{i})}{\prod_{i} (1-t_{j}x_{i})}
\right)
 \prod_{1 \le i \le j \le m}(1-t_{i}t_{j}),
\label{co-Bm}
\end{align}
where $T^{(m)}=\{t_{1},t_{2},\dots, t_{m}\}$.
Substituting the Schur function
\begin{align}
S_{\lambda }(T^{(m)})=
\frac{\det_{1 \le i,j \le m} (t_{i}^{\lambda_{j}+m-j})}
{\det_{1 \le i,j \le m} (t_{i}^{m-j})}
\label{SchDet}
\end{align}
into the left hand side of \eqref{co-Bm}, and multiplying 
the Vandermonde determinant 
\begin{align}
\det_{1 \le i,j \le m} (t_{i}^{m-j})
=\prod_{1 \le i < j \le m}(t_{i}-t_{j}) 
\label{Van}
\end{align}
on both sides, we obtain
\begin{multline}
\sum_{\lambda \in {\mathcal P}}
S_{[\lambda]}(X|Y)\det_{1 \le i,j \le m} (t_{i}^{\lambda_{j}+m-j})
=
\\
  
=\prod_{j=1}^{m}
\left(
\frac{\prod_{i} (1-t_{j}y_{i})}{\prod_{i} (1-t_{j}x_{i})}
\right)
 \prod_{i=1}^{m}(1-t_{i}^{2})
\prod_{1 \le i < j \le m}^{m}(t_{i}-t_{j})(1-t_{i}t_{j}).
\label{co-Bm2}
\end{multline}
In order to prove this, we need the following identity
\begin{align}
\det_{1 \le i,j \le m} (t_{i}^{m-j}-t_{i}^{m+j})
=\prod_{i=1}^{m}(1-t_{i}^{2})
\prod_{1 \le i < j \le m}^{m}(t_{i}-t_{j})(1-t_{i}t_{j}).
\label{mmdet}
\end{align}
By setting $t_{i} \to t_{i}+t_{i}^{-1}$ in \eqref{Van}, we obtain 
\begin{align}
\det_{1 \le i,j \le m} ((t_{i}+t_{i}^{-1})^{m-j})
=(-1)^{\frac{m(m-1)}{2}}\prod_{i=1}^{m}t_{i}^{1-m}
\prod_{1 \le i < j \le m}^{m}(t_{i}-t_{j})(1-t_{i}t_{j}).
\label{mmdet0}
\end{align}
The $(i,j)$-matrix element of the left hand side of \eqref{mmdet0} 
can be expanded as
\begin{multline}
(t_{i}+t_{i}^{-1})^{m-j}
= \sum_{k=0}^{m-j}\binom{m-j}{k}t_{i}^{2k-m+j}
\\
 
=
\begin{cases}
1 & \text{if} \quad m-j=0
\\
 
t_{i}^{m-j}+t_{i}^{-m+j}+
\sum_{k=1}^{\frac{m-j}{2}-1}\binom{m-j}{k}
(t_{i}^{-2k+m-j}+t_{i}^{2k-m+j})+\binom{m-j}{\frac{m-j}{2}} & \text{if} \quad m-j \in 2\mathbb{Z}_{\ge 1}
\\
 
t_{i}^{m-j}+t_{i}^{-m+j}+
\sum_{k=1}^{\frac{m-j-1}{2}}\binom{m-j}{k}
(t_{i}^{-2k+m-j}+t_{i}^{2k-m+j}) &
 \! \! \! \! 
 \text{if} \quad m-j \in 2\mathbb{Z}_{\ge 0}+1
\end{cases}
\label{expan}
\end{multline}
Thus, in the left hand side of \eqref{mmdet0}, 
by repeatedly performing the operation of subtracting 
$\binom{m-j}{k}$ times the $(j+2k)$-th column from the 
 $j$-th column of the matrix, for $k=1,2,\dots , (m-j)/2$ 
 if $m-j \in 2\mathbb{Z}_{\ge 1}$, and 
 for $k=1,2,\dots , (m-j-1)/2$ 
 if $m-j \in 2\mathbb{Z}_{\ge 1}+1$, 
 starting from $j=m-2$ down to $j=1$, 
we arrive at the following relation: 
\begin{align}
\det_{1 \le i,j \le m} ((t_{i}+t_{i}^{-1})^{m-j})
&=\frac{1}{2}\det_{1 \le i,j \le m} (t_{i}^{m-j}+t_{i}^{-m+j}).
\label{mmdet1}
\\
 
&=
\frac{(-1)^{\frac{m(m-1)}{2}}}{2}\det_{1 \le i,j \le m} (t_{i}^{j-1}+t_{i}^{-j+1}).
\label{mmdet2}
\end{align}
Note that the prefactor $1/2$ in the right hand side of 
\eqref{mmdet1} is necessary since 
$(t_{i}^{m-j}+t_{i}^{-m+j})$ becomes $2$ at $j=m$ while \eqref{expan} becomes $1$. 
Multiplying $(-1)^{\frac{m(m-1)}{2}}\prod_{i=1}^{m}t_{i}^{m-1}
(1-t_{i}^{2})$ on both sides of \eqref{mmdet1}, we obtain
\begin{multline}
(-1)^{\frac{m(m-1)}{2}}\prod_{i=1}^{m}t_{i}^{m-1}
(1-t_{i}^{2})
\det_{1 \le i,j \le m} ((t_{i}+t_{i}^{-1})^{m-j})
\\
 
=
\frac{1}{2}\det_{1 \le i,j \le m} (t_{i}^{m+j-2}-t_{i}^{m+j}+
t_{i}^{m-j}-t_{i}^{m-j+2}).
\label{mmdet3}
\end{multline}
Thus, in the right hand side of \eqref{mmdet3}, 
after multiplying the first column of the matrix by the prefactor 
$1/2$,
we perform a sequence of column operations in strictly descending order of the column index $j$, starting from $j=m$ down to $j=3$.
Specifically, for each such $j$, we add the $(j-2k)$-th column 
to the $j$-th column, where $k=1,2,\dots ,(j-1)/2$ 
 if $j \in 2\mathbb{Z}_{\ge 1}+1$, and 
 for $k=1,2,\dots ,j/2-1$ if $j \in 2\mathbb{Z}_{\ge 2}$.
Through this process, we find that \eqref{mmdet3} is equivalent to 
$\det_{1 \le i,j \le m} (t_{i}^{m-j}-t_{i}^{m+j})$, 
and thus \eqref{mmdet0} is equivalent to \eqref{mmdet}.

Let us modify the right hand side of \eqref{co-Bm2} as
\begin{multline}
\text{r.h.s. of \eqref{co-Bm2}}=
\prod_{j=1}^{m}
\left(
\frac{\prod_{i} (1-t_{j}y_{i})}{\prod_{i} (1-t_{j}x_{i})}
\right)
\det_{1 \le i,j \le m} (t_{i}^{m-j}-t_{i}^{m+j})
\quad \text{[by \eqref{mmdet}]}
\\
 
=\prod_{j=1}^{m}
\left(
\sum_{k_{j}=0}^{\infty} h_{k_{j}}(X|Y)t^{k_{j}}_{j}
\right)
\det_{1 \le i,j \le m} (t_{i}^{m-j}-t_{i}^{m+j})
 \quad \text{[by \eqref{genh}]}
\\
 
=
\left(
\sum_{k_{1}=0}^{\infty}
\dots 
\sum_{k_{m}=0}^{\infty}
\prod_{i=1}^{m}
 h_{k_{i}}(X|Y)t^{k_{i}}_{i}
\right)
\sum_{\sigma \in \mathcal{S}_{m}}
\mathrm{sgn}(\sigma)
\prod_{i=1}^{m}
(t_{i}^{m-\sigma(i)}-t_{i}^{m+\sigma(i)})
\\
 
=
\sum_{k_{1}=0}^{\infty}
\dots 
\sum_{k_{m}=0}^{\infty}
\sum_{\sigma \in \mathcal{S}_{m}}
\sum_{\xi_{1} \in \{-1,1\}}
\dots
\sum_{\xi_{m} \in \{-1,1\}}
\mathrm{sgn}(\sigma)
\prod_{i=1}^{m}
 h_{k_{i}}(X|Y)\xi_{i} t^{k_{i}+m-\xi_{i}\sigma(i)}_{i},
\end{multline}
where $\mathcal{S}_{m}$ denotes the symmetric group on $\{1,2,\dots ,m \}$.
   
By setting $\eta_{i}=k_{i}+m-\xi_{i}\sigma(i)$, we obtain
\begin{multline}
=
\sum_{\eta_{1}=0}^{\infty}
\dots 
\sum_{\eta_{m}=0}^{\infty}
\sum_{\sigma \in \mathcal{S}_{m}}
\sum_{\xi_{1} \in \{-1,1\}}
\dots
\sum_{\xi_{m} \in \{-1,1\}}
\mathrm{sgn}(\sigma)
\prod_{i=1}^{m}
 h_{\eta_{i}-m+\xi_{i}\sigma(i)}(X|Y)\xi_{i} t^{\eta_{i}}_{i}
 \\
 
=
\sum_{\eta_{1}=0}^{\infty}
\dots 
\sum_{\eta_{m}=0}^{\infty}
\sum_{\sigma \in \mathcal{S}_{m}}
\mathrm{sgn}(\sigma)
\prod_{i=1}^{m}
 (h_{\eta_{i}-m+\sigma(i)}(X|Y)-
 h_{\eta_{i}-m-\sigma(i)}(X|Y)) t^{\eta_{i}}_{i}
 \\
 
=
\sum_{\eta_{1}=0}^{\infty}
\dots 
\sum_{\eta_{m}=0}^{\infty}
\det_{1 \le i,j \le m} (h_{\eta_{i}-m+j}(X|Y)-
 h_{\eta_{i}-m-j}(X|Y)) \prod_{i=1}^{m} t^{\eta_{i}}_{i} .
\end{multline}
  
If any of the elements of $\{\eta_{1},\eta_{2},\dots ,\eta_{m}\}$ are equal to each other, the determinant above becomes zero, so by rearranging the rows, it takes the following form.
\begin{multline}
 
=
\sum_{\eta_{1}>\eta_{2} >\dots >\eta_{m} \ge 0}
\sum_{\sigma \in \mathcal{S}_{m}}
\mathrm{sgn}(\sigma)
\det_{1 \le i,j \le m} (h_{\eta_{i}-m+j}(X|Y)-
 h_{\eta_{i}-m-j}(X|Y)) \prod_{i=1}^{m} t^{\eta_{\sigma(i)}}_{i}
\\
 
=
\sum_{\eta_{1}>\eta_{2} >\dots >\eta_{m} \ge 0}
\det_{1 \le i,j \le m} (h_{\eta_{i}-m+j}(X|Y)-
 h_{\eta_{i}-m-j}(X|Y)) 
 \det_{1 \le i,j \le m}( t^{\eta_{j}}_{i}).
\end{multline}
   
By setting 
$\eta_{i}=\lambda_{i}+m-i$, we obtain 
\begin{multline}
=
\sum_{\lambda_{1} \ge \lambda_{2} \ge
 \dots \ge \lambda_{m} \ge 0}
\det_{1 \le i,j \le m} (h_{\lambda_{i}-i+j}(X|Y)-
 h_{\lambda_{i}-i-j}(X|Y)) 
 \det_{1 \le i,j \le m}( t^{\lambda_{j}+m-j}_{i})
 \\
 =\text{[left hand side of \eqref{co-Bm2}]}.
\end{multline}
This proves \eqref{co-Bm}, and thus \eqref{co-B}.

Let us set $(X,Y)\to (X  ,Y \sqcup \{1,-1 \})$ 
in \eqref{co-A}, and modify this as follows:
\begin{multline}
\sum_{\lambda \in {\mathcal P}}
S_{\lambda}(X |Y \sqcup 
 \{1,-1\}) S_{\lambda }(T)
=\prod_{j}
\left(
\frac{(1-t_{j})(1+t_{j}) \prod_{i}(1-t_{j}y_{i})}
{\prod_{i} (1-t_{j}x_{i})}
\right)
 \\ 
 
=\prod_{j }
\left(
\frac{ \prod_{i}(1-t_{j}y_{i})}{\prod_{i} (1-t_{j}x_{i})}
\right)\prod_{i \le j}(1-t_{i}t_{j}) 
 \times \frac{1}{\prod_{i < j}(1-t_{i}t_{j}) }
  \\
 
=\sum_{\mu \in {\mathcal P}}
S_{[\mu]}(X|Y )S_{\mu }(T)
\sum_{\kappa \in {\mathcal P}^{-}} S_{\kappa}(T) 
\qquad [\text{by \eqref{co-B},  \eqref{sum-L2}}]
\\
 
=\sum_{\lambda , \mu \in {\mathcal P}}
\sum_{\kappa \in {\mathcal P}^{-}} 
 \mathrm{LR}^{\lambda}_{\kappa , \mu} 
S_{[\mu]}(X|Y )
S_{\lambda}(T) 
\quad [\text{by \eqref{LR}}] .
\label{dc-5ap}
\end{multline}
By comparing the coefficients of $S_{\lambda}(T)$ on both sides of \eqref{dc-5ap}, we obtain \eqref{dc-4}. 
Similarly, all other relations can be proven by modifying \eqref{co-A} using  
\eqref{LR}: 
\begin{itemize}
    \item Case \eqref{dc-1a}: using \eqref{co-B} and \eqref{sum-L1};
    \item Case \eqref{dc-1b}: using \eqref{co-C} and \eqref{sum-L2};
    \item Case \eqref{dc-2a}: using \eqref{co-B} and \eqref{sum-L2};
    \item Case \eqref{dc-2b}: using \eqref{co-B}, \eqref{sum-S} and \eqref{signS};
    \item Case \eqref{dc-3a}: using \eqref{co-C} and \eqref{sum-L1};
    \item Case \eqref{dc-3b}: using \eqref{co-C}, \eqref{sum-S} and \eqref{signS};
 \item Case \eqref{dc-4}: using \eqref{co-B} and \eqref{sum-L2};   
    \item Case \eqref{dc-4du}: using \eqref{co-C} and \eqref{sum-L1}.
\end{itemize}
Alternatively, one can derive \eqref{dc-1b} from \eqref{dc-1a},
\eqref{dc-3a} from \eqref{dc-2a}, 
\eqref{dc-3b} from \eqref{dc-2b}, and \eqref{dc-4du} from \eqref{dc-4} by using \eqref{LRtran}, 
\eqref{A-dual} and \eqref{BCD-dual}.

\label{main-th}
The character formulas \eqref{de-BB0}--\eqref{de-D20} 
can be expressed in terms of supersymmetric Schur functions as follows.
\begin{flalign}
& U_{q}(\mathfrak{so}(2r+1)^{(1)}), \quad a \in \{1,2,\dots , r\}: 
& 
& \mathrm{ch}\, W^{(a)}_{(1+\delta_{ar})m}
=
S_{(m^{a})}(\mathbf{x} \sqcup \mathbf{x}^{-1} \mid \{-1\}), &
\label{de-BB00}
\end{flalign}

\begin{flalign}
& U_{q}(\mathfrak{sl}(2r+1)^{(2)}), \quad a \in \{1,2,\dots , r\}:
&
& \mathrm{ch}\, W^{(a)}_{m}
=
S_{(m^{a})}(\mathbf{x} \sqcup \{1\} \sqcup \mathbf{x}^{-1} \mid \emptyset), &
\label{de-t2B00}
\end{flalign}

\begin{flalign}
& U_{q}(\mathfrak{sl}(2r)^{(2)}), \quad a \in \{1,2,\dots , r\}:
&
& \mathrm{ch}\, W^{(a)}_{m}
=
S_{(m^{a})}(\mathbf{x} \sqcup \mathbf{x}^{-1} \mid \emptyset), &
\label{de-t3D00}
\end{flalign}

\begin{flalign}
& U_{q}(\mathfrak{so}(2r)^{(1)}), \quad a \in \{1,2,\dots , r-2\}:
&
& \mathrm{ch}\, W^{(a)}_{m}
=
S_{(m^{a})}(\mathbf{x} \sqcup \mathbf{x}^{-1} \mid \{1,-1\}), &
\label{de-D00}
\end{flalign}

\begin{flalign}
& U_{q}(\mathfrak{sp}(2r)^{(1)}), \quad a \in \{1,2,\dots , r-1\}:
&
& \mathrm{ch}\, W^{(a)}_{m}
=
S_{(m^{a})}(\mathbf{x} \sqcup \{1,-1\} \sqcup \mathbf{x}^{-1} \mid \emptyset), &
\label{de-C00}
\end{flalign}

\begin{flalign}
& U_{q}(\mathfrak{so}(2r+2)^{(2)}), \quad a \in \{1,2,\dots , r-1\}:
&
& \mathrm{ch}\, W^{(a)}_{m}
=
S_{(m^{a})}(\mathbf{x} \sqcup \{1,1\} \sqcup \mathbf{x}^{-1} \mid \{1,-1\}) &
\nonumber\\
& &
& =
S_{(m^{a})}(\mathbf{x} \sqcup \{1\} \sqcup \mathbf{x}^{-1} \mid \{-1\}). &
\label{de-D200}
\end{flalign}

It suffices to show that, in each case, the right-hand side of \eqref{de-BB00}--\eqref{de-D200} coincides with the corresponding equation in \eqref{de-BB0}--\eqref{de-D20}. This follows from the appropriate specialization of Proposition~\ref{pro-gen}, combined with the identities: 
\begin{align}
\ytableausetup{boxsize=0.5em}
\sum_{\nu \in {\mathcal P}}
 \mathrm{LR}^{(m^{a})}_{\nu , \mu} 
&=\begin{cases}
1 & \text{if} \quad \mu \in \mathcal{S}_{\tiny \ydiagram{1}} \\
0 & \text{otherwise},
\end{cases}
\label{LRrq1} 
\\
\sum_{\kappa \in {\mathcal P}^{-} } \mathrm{LR}^{(m^{a})}_{\kappa , \mu} 
&=
\begin{cases}
1 & \text{if} \quad \mu \in \mathcal{S}_{\tiny \ydiagram{1,1}} \\
0 & \text{otherwise},
\end{cases}
\label{LRrq2}
\\
  
\sum_{\kappa \in {\mathcal P}^{+} } \mathrm{LR}^{(m^{a})}_{\kappa , \mu} 
&=
\begin{cases}
1 & \text{if} \quad \mu \in \mathcal{S}_{\tiny \ydiagram{2}} \\
0 & \text{otherwise},
\end{cases}
\label{LRrq3}
\end{align}
which are consequences of \eqref{LR5}. 

Specifically:

\medskip
\noindent
{\bf (i) $U_q(\mathfrak{so}(2r+1)^{(1)})$.}
By setting 
\[
X=\mathbf{x} \sqcup \mathbf{x}^{-1}, 
\quad Y=\emptyset , \quad \xi=-1, \quad \lambda=(m^{a}) 
\]
in \eqref{dc-2a} and applying \eqref{LRrq2}, one can verify that the right-hand side of \eqref{de-BB00} coincides with that of \eqref{de-BB0}.
    

\medskip
\noindent
{\bf (ii) $U_q(\mathfrak{sl}(2r+1)^{(2)})$.}
By setting 
\[
X=\mathbf{x} \sqcup \{1 \} \sqcup \mathbf{x}^{-1}, 
\quad Y=\emptyset , \quad \lambda=(m^{a}) 
\]
in \eqref{dc-1a} and applying \eqref{LRrq3}, one can verify that the right-hand side of \eqref{de-t2B00} coincides with that of \eqref{de-t2B0}.
    

\medskip
\noindent
{\bf (iii) $U_q(\mathfrak{sl}(2r)^{(2)})$.}
By setting 
\[
X=\mathbf{x} \sqcup \mathbf{x}^{-1}, 
\quad Y=\emptyset , \quad \lambda=(m^{a}) 
\]
in \eqref{dc-1a} and applying \eqref{LRrq3}, 
one can verify that the right-hand side of \eqref{de-t3D00} coincides with that of \eqref{de-t3D0}.

\medskip
\noindent
{\bf (iv) $U_q(\mathfrak{so}(2r)^{(1)})$.}
By setting 
\[
X=\mathbf{x} \sqcup \mathbf{x}^{-1}, 
\quad Y=\emptyset , \quad \lambda=(m^{a}) 
\]
in \eqref{dc-4} and applying \eqref{LRrq2}
 , one can verify that the right-hand side of \eqref{de-D00}
  coincides with that of \eqref{de-D0}.

    
\medskip
\noindent
{\bf (v) $U_q(\mathfrak{sp}(2r)^{(1)})$.}
By setting 
\[
X=\mathbf{x} \sqcup \mathbf{x}^{-1}, 
\quad Y=\emptyset , \quad \lambda=(m^{a}) 
\]
in \eqref{dc-4du} and applying \eqref{LRrq3}, 
 one can verify that the right-hand side of \eqref{de-C00}
  coincides with that of \eqref{de-C0}.

    
\medskip
\noindent
{\bf (vi) $U_q(\mathfrak{so}(2r+2)^{(2)})$.}
By setting 
\[
X=\mathbf{x} \sqcup \{1,1 \} \sqcup \mathbf{x}^{-1}, 
\quad Y=\{1\} , \quad \xi=-1, \quad \lambda=(m^{a}) 
\]
in \eqref{dc-2b} and applying \eqref{SP-A} and \eqref{LRrq1}
 , one can verify that the right-hand side of \eqref{de-D200}
  coincides with that of \eqref{de-D20}.
